let frequencies_view: &[size_t] =
    unsafe { core::slice::from_raw_parts(frequencies, n as usize) };
let bitlengths_view: &mut [c_uint] =
    unsafe { core::slice::from_raw_parts_mut(bitlengths, n as usize) };
let mut pool: NodePool = NodePool {
    next: ::core::ptr::null_mut::<Node>(),
};
let mut i: c_int = 0;
let mut numsymbols: c_int = 0 as c_int;
let mut numBoundaryPMRuns: c_int = 0;
let mut nodes: *mut Node = ::core::ptr::null_mut::<Node>();
let mut lists: *mut [*mut Node; 2] = ::core::ptr::null_mut::<[*mut Node; 2]>();
let mut leaves_buf: Vec<Node> = Vec::with_capacity(n as usize);
let leaves: *mut Node = leaves_buf.as_mut_ptr();

for dst in bitlengths_view.iter_mut() {
    *dst = 0 as c_uint;
}

for (idx, &freq) in frequencies_view.iter().enumerate() {
    if freq != 0 {
        unsafe {
            // SAFETY: `leaves` points to `leaves_buf` capacity of `n` Nodes, and
            // `numsymbols < n` because we push at most once per input element.
            let leaf = leaves.add(numsymbols as usize);
            (*leaf).weight = freq;
            (*leaf).count = idx as c_int;
        }
        numsymbols += 1;
    }
}
unsafe {
    // SAFETY: exactly `numsymbols` elements were initialized in the loop above.
    leaves_buf.set_len(numsymbols as usize);
}

if (1 as c_int) << maxbits < numsymbols {
    return 1 as c_int;
}
if numsymbols == 0 as c_int {
    return 0 as c_int;
}
if numsymbols == 1 as c_int {
    let count0 = unsafe {
        // SAFETY: `numsymbols == 1`, so element 0 is initialized.
        (*leaves.add(0)).count as usize
    };
    bitlengths_view[count0] = 1 as c_uint;
    return 0 as c_int;
}
if numsymbols == 2 as c_int {
    let (count0, count1) = unsafe {
        // SAFETY: `numsymbols == 2`, so elements 0 and 1 are initialized.
        ((*leaves.add(0)).count as usize, (*leaves.add(1)).count as usize)
    };
    bitlengths_view[count0] = bitlengths_view[count0].wrapping_add(1);
    bitlengths_view[count1] = bitlengths_view[count1].wrapping_add(1);
    return 0 as c_int;
}
i = 0 as c_int;
while i < numsymbols {
    let leaf = unsafe {
        // SAFETY: `i < numsymbols <= leaves_buf.len()`.
        &mut *leaves.add(i as usize)
    };
    let weight = leaf.weight;
    if weight
        >= (1 as c_int as size_t)
            << (::core::mem::size_of::<size_t>() as usize)
                .wrapping_mul(CHAR_BIT as usize)
                .wrapping_sub(9 as usize)
    {
        return 1 as c_int;
    }
    leaf.weight = weight << 9 as c_int | leaf.count as size_t;
    i += 1;
}

